const qs = [
  '(raises OR raised OR secures OR closes) (seed OR "pre-seed" OR "Series A" OR "Series B" OR "funding round") (startup OR scaleup) (UK OR London OR Manchester OR Edinburgh OR Bristol OR Cambridge OR Oxford OR Leeds OR Birmingham) when:2d',
  '(raises OR secures) funding (startup OR scaleup) (Ireland OR Dublin OR Cork OR Galway) when:2d',
  'AI startup (raises OR secures OR lands) million (UK OR London OR British) when:2d',
  '"Series A" (London OR UK OR British) when:2d',
  '("seed round" OR "pre-seed") (UK OR London OR British OR Irish) startup when:2d'
];
return qs.map(q => ({ json: { q, url: 'https://news.google.com/rss/search?q=' + encodeURIComponent(q) + '&hl=en-GB&gl=GB&ceid=GB:en' } }));

const un = s => String(s || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const seen = new Set(); const out = [];
for (const it of $input.all()) {
  const xml = String(it.json.body || '');
  const re = /<item>([\s\S]*?)<\/item>/g; let m;
  while ((m = re.exec(xml))) {
    const b = m[1];
    const title = un((b.match(/<title>([\s\S]*?)<\/title>/) || [,''])[1]);
    const link = un((b.match(/<link>([\s\S]*?)<\/link>/) || [,''])[1]);
    const date = un((b.match(/<pubDate>([\s\S]*?)<\/pubDate>/) || [,''])[1]);
    const desc = un((b.match(/<description>([\s\S]*?)<\/description>/) || [,''])[1]).slice(0, 400);
    const src = un((b.match(/<source[^>]*>([\s\S]*?)<\/source>/) || [,''])[1]);
    if (!link || seen.has(link)) continue; seen.add(link);
    if (!/rais|secur|clos|land|fund|invest|round|seed|series/i.test(title)) continue;
    out.push({ json: { title, url: link, date: date ? new Date(date).toISOString().slice(0, 10) : null, text: desc, source: src } });
  }
}
return out;

let seen = []; try { seen = JSON.parse(String($input.first().json.body || '[]')).map(r => r.url); } catch (e) { seen = []; }
const s = new Set(seen);
return $('Articles').all().filter(i => !s.has(i.json.url)).slice(0, 40);

const arts = $('Unseen articles').all();
const out = [];
$input.all().forEach((it, i) => {
  const o = it.json.output || {}; const a = (arts[i] || {}).json || {};
  const ok = o.is_raise === true && o.uk_or_ie === true && (o.confidence || 0) >= 0.6 && !!o.company;
  out.push({ json: { url: a.url, title: a.title, keep: ok, company: o.company || '', domain: o.domain || '', amount: o.amount || '', stage: o.stage || '', event_date: o.event_date || a.date, location: o.location || '', is_ai: o.is_ai === true, summary: o.summary || '' } });
});
return out;

const kept = $('Keep?').all();
const news = [];
$input.all().forEach((it, i) => {
  let r = null; try { r = JSON.parse(String(it.json.body || '[]'))[0]; } catch (e) {}
  const k = (kept[i] || {}).json || {};
  if (r && r.outcome === 'new') news.push({ ...k, account_id: r.account_id });
});
if (!news.length) return [];
const lines = news.map(n => '- ' + n.company + (n.is_ai ? ' (AI)' : '') + ': ' + (n.amount || 'undisclosed') + ' ' + (n.stage || '') + ', ' + (n.location || 'UK') + '. ' + n.summary + '\n  ' + n.url);
const body = 'Hi Jamie, ' + news.length + ' freshly funded UK/IE compan' + (news.length > 1 ? 'ies' : 'y') + ' not in the book, found in the last hour.\n\nCheck the CRM first. If nobody owns it, add it and it is yours.\n\n' + lines.join('\n') + '\n\nIt will be on the call list within the hour with the opener written, marked NET NEW in Evidence.\n\nThanks';
return [{ json: { subject: 'New money: ' + news.map(n => n.company).join(', ').slice(0, 80), body, count: news.length } }];
